using SaferSurface;
static class Test {
 static int n; static void Check(bool ok,string name){if(!ok) throw new Exception(name);n++;}
 static void Main(){var c=new SurfaceConfig(); Check(c.Validate()==null,"valid defaults"); Check(c.SeasonalDaylight,"season default"); Check(SurfacePolicy.Daylight(c,12,5),"season sun at5 beats fixed hours");Check(!SurfacePolicy.Daylight(c,-1,12),"season dark at12 beats fixed hours"); c.SeasonalDaylight=false;Check(!SurfacePolicy.Daylight(c,12,8.99),"fixed before9");Check(SurfacePolicy.Daylight(c,-1,9),"fixed starts9");Check(!SurfacePolicy.Daylight(c,12,19),"fixed ends19");c.SeasonalDaylight=true;
 Check(!SurfacePolicy.Outside(c,8,0,0),"exact8");Check(SurfacePolicy.Outside(c,8.001,0,0),"beyond8");Check(SurfacePolicy.Outside(c,0,9,0),"3d");c.HorizontalDistance=true;Check(!SurfacePolicy.Outside(c,0,9,0),"horizontal");c.HorizontalDistance=false;
 Check(SurfacePolicy.Reject(c,true,true,false,false,9,0,0,true,true,true),"reject acquisition");
 Check(!SurfacePolicy.Reject(c,false,true,false,false,9,0,0,true,true,true),"vanilla invalid untouched");Check(!SurfacePolicy.Reject(c,true,false,false,false,9,0,0,true,true,true),"nonplayer");Check(!SurfacePolicy.Reject(c,true,true,true,false,9,0,0,true,true,true),"same pair pursuit");Check(SurfacePolicy.Reject(c,true,true,false,false,9,0,0,true,true,true),"different pair still capped");Check(!SurfacePolicy.Reject(c,true,true,false,true,9,0,0,true,true,true),"retaliation");Check(!SurfacePolicy.Reject(c,true,true,false,false,9,0,0,false,true,true),"monster shade");Check(!SurfacePolicy.Reject(c,true,true,false,false,9,0,0,true,false,true),"player shade");Check(!SurfacePolicy.Reject(c,true,true,false,false,9,0,0,true,true,false),"dimension unknown");
 Check(c.Includes("game:drifter-normal"),"drifter");Check(c.Includes("game:shiver-deep"),"shiver");Check(c.Includes("game:bowtorn-corrupt"),"bowtorn");Check(!c.Includes("game:wolf-male"),"wolf");Check(!c.Includes("game:drifter-boss"),"boss exclusion");c.MaximumRange=double.NaN;Check(c.Validate()!=null,"nan invalid");c.MaximumRange=8;c.CacheTtlMs=-1;Check(c.Validate()!=null,"ttl invalid");c.CacheTtlMs=500;
 // Cache identity contract: neither TTL nor stable ID can hide block/dimension changes.
 var key=new PositionStamp(1,2,3,0);Check(key==new PositionStamp(1,2,3,0),"same block");Check(key!=new PositionStamp(2,2,3,0),"block change");Check(key!=new PositionStamp(1,2,3,1),"dimension change");
 c.SeasonalDaylight=false;c.DayStartHour=19;c.DayEndHour=6;Check(c.Validate()==null,"wrapping window valid");Check(SurfacePolicy.Daylight(c,-1,23),"wrapping late");Check(SurfacePolicy.Daylight(c,-1,5),"wrapping early");Check(!SurfacePolicy.Daylight(c,1,6),"wrapping end exclusive");Check(!SurfacePolicy.Daylight(c,1,12),"wrapping midday out");c.DayStartHour=9;c.DayEndHour=19;c.SeasonalDaylight=true;
 Check(c.PreserveExistingPursuit&&c.VanillaDuringRetaliation&&c.VanillaDuringTemporalStorms&&c.VanillaInDarkLocations&&c.VanillaInUnstableRegions&&c.RequireBothEndpointsOnSurface,"exception defaults preserve contract");
 var dir=Directory.CreateTempSubdirectory("safer-surface-tests-");try {var path=Path.Combine(dir.FullName,"config.json");Check(ConfigFile.LoadOrCreate(path).MaximumRange==8,"new default file");foreach(var bad in new[]{"","null","[]","{","{\"MaximumRange\":-1}","{\"Enabled\":\"yes\"}","{\"Unknown\":1}","{\"Enabled\":true,\"enabled\":false}"}){File.WriteAllText(path,bad);bool threw=false;try{ConfigFile.LoadOrCreate(path);}catch{threw=true;}Check(threw,"invalid config rejected");Check(File.ReadAllText(path)==bad,"original config byte preserved");}}finally{dir.Delete(true);}
 _=Measure(c);long allocated=Measure(c);Check(allocated==0,"policy allocates zero bytes (observed "+allocated+")");Console.WriteLine($"PASS {n} policy/config assertions; 100000 warmed hot-path decisions: {allocated} allocated bytes"); }
 [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)] static long Measure(SurfaceConfig c){long before=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<100000;i++)SurfacePolicy.Reject(c,true,true,false,false,9,0,0,true,true,true);return GC.GetAllocatedBytesForCurrentThread()-before;}
